from typing import Dict, Any, List

import boto3

def write_correlated_logs(events: List[Dict[str, Any]], config: Dict[str, Any] = None):
    config = config or {}
    client = boto3.client("logs", region_name=config.get("region"))
    log_events = []
    for event in events:
        log_events.append({
            "timestamp": int(event.get("timestamp_ms", time.time() * 1000)),
            "message": json.dumps(event["event"]),
        })

    response = client.put_log_events(
        logGroupName=config["log_group"],
        logStreamName=config["log_stream"],
        logEvents=log_events,
    )
    if response.get("rejectedLogEventsInfo") or response.get("rejectedEntityInfo"):
        raise RuntimeError("The logging service rejected some events")
    return {"submitted": True}

from typing import Dict, Any
from observability_client import ObservabilityClient
from observability_models import SafetyCheckRequest
from google.cloud.aiplatform_v1beta1.types import HarmCategory

def check_log_text_safety(text_content: str, project_id: str, location: str) -> Dict[str, Any]:
    client = ObservabilityClient(region_name="us-east-1", project_id=project_id, location=location)
    model = client.get_aiplatform_model("gemini-pro") # Using gemini-pro for safety attributes as well

    response = model.predict(prompt=text_content)
    safety_attributes = response.safety_attributes

    # Convert safety_attributes to a more friendly dictionary for output
    safety_report = {
        "text_content": text_content,
        "safety_ratings": []
    }

    if safety_attributes:
        for category, score in zip(safety_attributes.categories, safety_attributes.scores):
            safety_report["safety_ratings"].append({
                "category": HarmCategory(category).name, # Convert category enum to string name
                "score": score
            })

    return safety_report

